-- case: perf/join-terms-on-one-table-inner
CREATE TABLE t(a, b, c);
INSERT INTO t SELECT value % 30, value % 7, value FROM generate_series(1, 300);
CREATE TABLE u(a, b, c);
INSERT INTO u SELECT value % 11, value % 5, value * 2 FROM generate_series(1, 120);
CREATE TABLE w(a, b, c);
INSERT INTO w SELECT value % 4, value % 3, value FROM generate_series(1, 40);
SELECT count(*) FROM t x, t y WHERE x.a = 1 AND y.a = 0;
SELECT count(*) FROM t x, t y WHERE y.a = 0 AND x.a = 1;
SELECT count(*) FROM t x, u y WHERE x.a = 1 AND y.a = 0;
SELECT count(*) FROM t x, u y WHERE x.a = 1;
SELECT count(*) FROM t x, u y WHERE y.a = 0;
SELECT count(*) FROM t x JOIN u y ON x.c = y.c + 1 WHERE x.a = 1 AND y.a = 0;
SELECT count(*) FROM t x JOIN u y ON x.b = y.b WHERE x.a < 3 AND y.a > 5 AND x.c <> y.c;
SELECT x.c, y.c FROM t x, u y WHERE x.a = 1 AND y.a = 0 ORDER BY x.c, y.c;
SELECT count(*) FROM t x, u y WHERE x.a = 1 OR y.a = 0;
SELECT count(*) FROM t x, u y WHERE (x.a = 1 OR x.b = 2) AND (y.a = 0 OR y.b = 4);
SELECT count(*) FROM t x, u y WHERE x.a IS NULL AND y.a = 0;
SELECT count(*) FROM t x, u y WHERE x.a = 1 AND y.a = 0 AND x.b = y.b;
-- case: perf/join-terms-on-one-table-three-tables
CREATE TABLE t(a, b, c);
INSERT INTO t SELECT value % 30, value % 7, value FROM generate_series(1, 300);
CREATE TABLE u(a, b, c);
INSERT INTO u SELECT value % 11, value % 5, value * 2 FROM generate_series(1, 120);
CREATE TABLE w(a, b, c);
INSERT INTO w SELECT value % 4, value % 3, value FROM generate_series(1, 40);
SELECT count(*) FROM t x, u y, w z WHERE x.a = 1 AND y.a = 0 AND z.a = 2;
SELECT count(*) FROM t x, u y, w z WHERE z.a = 2 AND y.a = 0 AND x.a = 1;
SELECT count(*) FROM t x, u y, w z WHERE x.a = 1 AND y.a = 0 AND z.a = 2 AND x.b = z.b;
SELECT count(*) FROM t x JOIN u y ON y.b = x.b JOIN w z ON z.c = y.b WHERE x.a = 1 AND y.a = 0;
SELECT x.c, y.c, z.c FROM t x, u y, w z WHERE x.a = 1 AND y.a = 0 AND z.a = 2 AND x.c < 60 AND y.c < 40 ORDER BY 1, 2, 3;
-- case: perf/join-terms-on-one-table-left-join
CREATE TABLE t(a, b, c);
INSERT INTO t SELECT value % 30, value % 7, value FROM generate_series(1, 300);
CREATE TABLE u(a, b, c);
INSERT INTO u SELECT value % 11, value % 5, value * 2 FROM generate_series(1, 120);
CREATE TABLE w(a, b, c);
INSERT INTO w SELECT value % 4, value % 3, value FROM generate_series(1, 40);
SELECT count(*) FROM t x LEFT JOIN u y ON x.c = y.c WHERE x.a = 1;
SELECT count(*) FROM t x LEFT JOIN u y ON x.c = y.c WHERE x.a = 1 AND y.a IS NULL;
SELECT count(*) FROM t x LEFT JOIN u y ON x.c = y.c WHERE y.a = 0;
SELECT count(*) FROM t x LEFT JOIN u y ON x.c = y.c WHERE x.a = 1 AND y.a = 1;
SELECT count(*) FROM t x LEFT JOIN u y ON x.b = y.b AND y.a = 0 WHERE x.a = 1;
SELECT count(*) FROM t x LEFT JOIN u y ON x.b = y.b AND y.a = 0 WHERE x.a = 1 AND y.c IS NULL;
SELECT count(*) FROM t x LEFT JOIN u y ON y.a = 0 LEFT JOIN w z ON z.a = x.a WHERE x.a = 1 AND z.b = 1;
SELECT x.c, y.c FROM t x LEFT JOIN u y ON x.c = y.c WHERE x.a = 2 ORDER BY x.c;
SELECT count(*) FROM t x, u y LEFT JOIN w z ON z.a = y.a WHERE x.a = 1 AND y.a = 0 AND z.b IS NOT NULL;
-- case: perf/join-terms-on-one-table-right-and-full-join
CREATE TABLE t(a, b, c);
INSERT INTO t SELECT value % 30, value % 7, value FROM generate_series(1, 300);
CREATE TABLE u(a, b, c);
INSERT INTO u SELECT value % 11, value % 5, value * 2 FROM generate_series(1, 120);
CREATE TABLE w(a, b, c);
INSERT INTO w SELECT value % 4, value % 3, value FROM generate_series(1, 40);
SELECT count(*) FROM t x RIGHT JOIN u y ON x.c = y.c WHERE y.a = 0;
SELECT count(*) FROM t x RIGHT JOIN u y ON x.c = y.c WHERE x.a = 1;
SELECT count(*) FROM t x RIGHT JOIN u y ON x.c = y.c WHERE x.a IS NULL;
SELECT count(*) FROM t x FULL JOIN u y ON x.c = y.c WHERE x.a = 1 AND y.a = 0;
SELECT count(*) FROM t x FULL JOIN u y ON x.c = y.c WHERE x.a IS NULL OR y.a IS NULL;
SELECT count(*) FROM t x, u y RIGHT JOIN w z ON z.a = y.a WHERE x.a = 1 AND z.b = 1;
SELECT count(*) FROM t x, u y FULL JOIN w z ON z.a = y.a WHERE x.a = 1 AND y.a IS NULL;
-- case: perf/join-terms-with-subqueries-and-functions
CREATE TABLE t(a, b, c);
INSERT INTO t SELECT value % 30, value % 7, value FROM generate_series(1, 300);
CREATE TABLE u(a, b, c);
INSERT INTO u SELECT value % 11, value % 5, value * 2 FROM generate_series(1, 120);
CREATE TABLE w(a, b, c);
INSERT INTO w SELECT value % 4, value % 3, value FROM generate_series(1, 40);
SELECT count(*) FROM t x, u y WHERE x.a = 1 AND y.a = 0 AND x.c IN (SELECT c FROM w);
SELECT count(*) FROM t x, u y WHERE x.a = (SELECT min(a) + 1 FROM w) AND y.a = 0;
SELECT count(*) FROM t x, u y WHERE x.a = 1 AND y.a = 0 AND EXISTS (SELECT 1 FROM w z WHERE z.c = x.b);
SELECT count(*) FROM t x, u y WHERE abs(x.a - 1) = 0 AND length(y.c) = 1;
SELECT count(*) FROM t x, u y WHERE x.a = 1 AND y.a = 0 AND random() IS NOT NULL;
SELECT count(*) FROM t x, json_each('[1,2,3]') j WHERE x.a = j.value AND x.b = 1;
SELECT count(*) FROM t x, u y WHERE x.a = 1 AND y.a = 0 AND x.c || '' <> y.c || 'z';
-- case: perf/upsert-onto-keys-in-one-leaf-same-length
CREATE TABLE k(id INTEGER PRIMARY KEY, n INT, s TEXT);
INSERT INTO k SELECT value % 300, 1, 'aaaa' FROM generate_series(1, 3000) WHERE true ON CONFLICT(id) DO UPDATE SET n = n + 1, s = 'bbbb';
SELECT count(*), sum(n), min(n), max(n), min(s), max(s) FROM k;
SELECT id, n, s FROM k WHERE id IN (0, 1, 150, 299) ORDER BY id;
PRAGMA integrity_check;
-- case: perf/upsert-onto-keys-in-one-leaf-changing-length
CREATE TABLE k(id INTEGER PRIMARY KEY, n INT, s TEXT);
INSERT INTO k SELECT value % 200, value, 'v' || value FROM generate_series(1, 3000) WHERE true ON CONFLICT(id) DO UPDATE SET n = excluded.n, s = excluded.s || printf('%.*c', value % 5, 'x');
SELECT count(*), sum(n), sum(length(s)), min(s), max(s) FROM k;
SELECT id, n, s FROM k WHERE id IN (0, 1, 100, 199) ORDER BY id;
UPDATE k SET s = s || '!' WHERE id % 2 = 0;
SELECT count(*), sum(length(s)) FROM k;
PRAGMA integrity_check;
-- case: perf/insert-or-replace-onto-keys-in-one-leaf
CREATE TABLE k(id INTEGER PRIMARY KEY, n INT, s TEXT);
INSERT OR REPLACE INTO k SELECT value % 250, value, 'row ' || (value % 17) FROM generate_series(1, 3000);
SELECT count(*), sum(n), sum(length(s)), min(s), max(s) FROM k;
INSERT OR REPLACE INTO k SELECT value % 250, value * 2, 'r' FROM generate_series(1, 1000);
SELECT count(*), sum(n), sum(length(s)), min(s), max(s) FROM k;
PRAGMA integrity_check;
-- case: perf/upsert-onto-keys-with-an-index-and-a-unique-column
CREATE TABLE k(id INTEGER PRIMARY KEY, n INT, u INT UNIQUE, s TEXT);
CREATE INDEX kn ON k(n);
INSERT INTO k SELECT value % 120, value, value % 120 + 1000, 'x' FROM generate_series(1, 2400) WHERE true ON CONFLICT(id) DO UPDATE SET n = excluded.n, s = s || 'y';
SELECT count(*), sum(n), min(u), max(u), sum(length(s)) FROM k;
SELECT id FROM k WHERE n = 2400;
SELECT count(*) FROM k INDEXED BY kn WHERE n > 2300;
PRAGMA integrity_check;
-- case: perf/cascade-delete-of-scattered-children
PRAGMA foreign_keys = ON;
CREATE TABLE par(id INTEGER PRIMARY KEY);
CREATE TABLE ch(id INTEGER PRIMARY KEY, pid INT REFERENCES par(id) ON DELETE CASCADE, pad TEXT);
CREATE INDEX chp ON ch(pid);
INSERT INTO par SELECT value FROM generate_series(1, 100);
INSERT INTO ch SELECT value, value % 100 + 1, printf('%.*c', 40, 'p') FROM generate_series(1, 6000);
SELECT count(*) FROM par;
SELECT count(*) FROM ch;
DELETE FROM par WHERE id <= 40;
SELECT count(*) FROM par;
SELECT count(*), min(pid), max(pid) FROM ch;
DELETE FROM par WHERE id % 2 = 0;
SELECT count(*), min(pid), max(pid) FROM ch;
SELECT count(*) FROM ch WHERE pid IN (SELECT id FROM par);
PRAGMA foreign_key_check;
PRAGMA integrity_check;
DELETE FROM par;
SELECT count(*) FROM par;
SELECT count(*) FROM ch;
INSERT INTO par VALUES (1);
INSERT INTO ch VALUES (1, 1, 'again');
SELECT id, pid, pad FROM ch;
PRAGMA integrity_check;
-- case: perf/delete-of-scattered-rows-then-reinsert
CREATE TABLE ch(id INTEGER PRIMARY KEY, pid INT, pad TEXT);
CREATE INDEX chp ON ch(pid);
INSERT INTO ch SELECT value, value % 100 + 1, printf('%.*c', 40, 'p') FROM generate_series(1, 6000);
DELETE FROM ch WHERE pid <= 60;
SELECT count(*), min(pid), max(pid) FROM ch;
INSERT INTO ch SELECT value + 10000, value % 100 + 1, 'again' FROM generate_series(1, 500);
SELECT count(*), sum(pid), count(DISTINCT pad) FROM ch;
DELETE FROM ch WHERE pid > 20 AND pid <= 90;
SELECT count(*), min(pid), max(pid) FROM ch;
PRAGMA integrity_check;
