-- case: perf/long-text-values-in-rows
CREATE TABLE bt(id INTEGER PRIMARY KEY, s TEXT);
INSERT INTO bt SELECT value, printf('%.*c', 20000, char(97 + value % 26)) FROM generate_series(1, 60);
SELECT count(*), sum(length(s)), min(substr(s, 1, 3)), max(substr(s, 19998, 3)) FROM bt;
UPDATE bt SET s = s || 'tail' WHERE id % 3 = 0;
SELECT count(*), sum(length(s)) FROM bt;
DELETE FROM bt WHERE id % 2 = 0;
SELECT count(*), sum(length(s)) FROM bt;
PRAGMA integrity_check;
